from packaging.ranges import VersionRange
from packaging.specifiers import SpecifierSet


def version_range_contains(version: str, specifier_set: str) -> bool:
    """Check if a version is contained within a version range using the 'in' operator. version: A version string to check for membership in the range, e.g. '1.5' -> True. specifier_set: A specifier set string that defines the version range, e.g. '>=1.0,<2.0'."""
    try:
        range_obj = SpecifierSet(specifier_set).to_range()
        return version in range_obj
    except Exception as e:
        raise ValueError(f"invalid version range or version: {specifier_set!r}, {version!r}") from e

