from packaging.ranges import VersionRange


def version_range_full(admit_arbitrary: bool = True, prereleases: bool | None = None) -> str:
    """Create a version range that accepts all possible PEP 440 versions. admit_arbitrary: whether to admit arbitrary version strings; prereleases: whether to include pre-release versions. Example: version_range_full() -> '<VersionRange '(-inf, +inf)' arbitrary>'"""
    try:
        result = VersionRange.full(admit_arbitrary=admit_arbitrary, prereleases=prereleases)
        return str(result)
    except Exception as e:
        raise ValueError(f"Failed to create version range: {str(e)}")

from packaging.specifiers import Specifier


def specifier_contains(specifier: str, version: str, prereleases: bool | None = None) -> bool:
    """Return whether a specific version is contained in a specifier. specifier: A version specifier string, e.g., '>=1.2.3'. version: The version string to check for containment in the specifier. prereleases: Whether or not to match prereleases with this Specifier. If set to None (the default), it will follow the recommendation from PEP 440. >>> specifier_contains('>=1.2.3', '1.2.3') True"""
    try:
        spec = Specifier(specifier, prereleases=prereleases)
        return spec.contains(version, prereleases=prereleases)
    except Exception as e:
        raise ValueError(f"Invalid specifier or version: {e}")

from packaging.specifiers import SpecifierSet


def specifier_set_equal(left: str, right: str) -> bool:
    """The `==` operator with SpecifierSet objects, as in `left == right`. It is an operator, not a function: use it as an expression with `==`, never as a call of `__eq__`. At least one side is a SpecifierSet object.

    Example: specifier_set_equal(">=3.0,!=3.1", ">=3.0,!=3.1") -> True"""
    try:
        left_set = SpecifierSet(left)
        right_set = SpecifierSet(right)
        return left_set == right_set
    except Exception as e:
        raise ValueError(f"Invalid specifier set: {e}")

