def is_version_range_subset(range1: str, range2: str) -> bool:
    """Check if every version in range1 is also in range2. range1: a version range specifier, e.g. '>=1.0,<2.0' -> true. range2: another version range to check against."""
    try:
        version_range1 = SpecifierSet(range1).to_range()
        version_range2 = SpecifierSet(range2).to_range()
        return version_range1.is_subset(version_range2)
    except Exception as e:
        raise ValueError(f"invalid version range: {e}")

