from packaging.version import Version


def create_version_from_parts(
    release: list[int],
    epoch: int | None = 0,
    pre: list[str | int] | None = None,
    post: int | None = None,
    dev: int | None = None,
    local: str | None = None,
) -> str:
    """Construct a Version object from individual components. release: The release tuple is required, e.g. [1, 2, 3] -> "1.2.3". epoch: Epoch value, e.g. 1 -> "1!1.2.3". pre: Pre-release identifier and number, e.g. ["b", 1] -> "1.2.3b1". post: Post-release number, e.g. 1 -> "1.2.3.post1". dev: Development release number, e.g. 1 -> "1.2.3.dev1". local: Local version identifier, e.g. "ubuntu1" -> "1.2.3+ubuntu1". Example: create_version_from_parts(release=[1,2,3]) -> "1.2.3"."""
    try:
        # Convert pre to tuple if provided
        pre_tuple = None
        if pre is not None:
            if len(pre) != 2:
                raise ValueError("pre must be a list with exactly two elements: [identifier, number]")
            pre_tuple = (str(pre[0]), int(pre[1]))

        # Validate inputs
        if not isinstance(release, list):
            raise ValueError("release must be a list of integers")
        if not all(isinstance(x, int) for x in release):
            raise ValueError("all elements in release must be integers")

        # Create the version using the library's from_parts method
        version_obj = Version.from_parts(
            epoch=epoch or 0,
            release=tuple(release),
            pre=pre_tuple,
            post=post,
            dev=dev,
            local=local
        )

        return str(version_obj)

    except Exception as e:
        if isinstance(e, ValueError):
            raise e
        raise ValueError(f"Failed to create version from parts: {str(e)}")

from packaging.version import Version


def version_less_than(left: str, right: str) -> bool:
    """The `<` operator with Version objects, as in `left < right`. It is an operator, not a function: use it as an expression with `<`, never as a call of `__lt__`. At least one side is a Version object.

    Example: version_less_than("1.0a5", "1.0") -> True"""
    try:
        return Version(left) < Version(right)
    except Exception as e:
        raise ValueError(f"invalid version string: {e}")

from packaging.version import Version


def version_greater_than(left: str, right: str) -> bool:
    """The `>` operator with Version objects, as in `left > right`. It is an operator, not a function: use it as an expression with `>`, never as a call of `__gt__`. At least one side is a Version object.

    Example: version_greater_than("2.0", "1.5") -> True"""
    try:
        left_version = Version(left)
        right_version = Version(right)
        return left_version > right_version
    except Exception as e:
        raise ValueError(f"Invalid version string: {e}")
